// And groups predicates with the AND operator between them.
func And(predicates ...predicate.NodeAssignment) predicate.NodeAssignment {
	return predicate.NodeAssignment(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.NodeAssignment) predicate.NodeAssignment {
	return predicate.NodeAssignment(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.NodeAssignment) predicate.NodeAssignment {
	return predicate.NodeAssignment(sql.NotPredicates(p))
}
